// ⚠️ TU URL DE GOOGLE APPS SCRIPT ENLAZADA
const GAS_URL = "https://script.google.com/macros/s/AKfycbwZcUqc3J2C0cuuAUf4FBEHlBhjBc2mnWG2zvgzgZEJ86nqN2cqLDD2LOgXzh6hIsKVgg/exec";

// 🖼️ Logo del negocio en Base64 (así no depende de una carpeta de imágenes
// y puede usarse tanto en las pantallas HTML como dentro del PDF exportado)
const LOGO_BASE64 = "data:image/png;base64,";

// ✍️ Firma digital del negocio en Base64 (para comprobantes PDF/Imagen)
const FIRMA_BASE64 = "data:image/png;base64,";

// Función para verificar si un rol pertenece a un administrador
function esAdmin(rol) {
    if (!rol) return false;
    return String(rol).trim().toLowerCase().startsWith("admin");
}

// Flujo de seguridad: Protege las vistas de accesos no autorizados
function verificarSesion(requiereAdmin) {
    const sesionRaw = localStorage.getItem('sesion');

    if (!sesionRaw) {
        // Si no hay sesión iniciada, redirige obligatoriamente al login (index.html)
        window.location.href = "index.html";
        return null;
    }

    const sesion = JSON.parse(sesionRaw);
    if (requiereAdmin && !esAdmin(sesion.rol)) {
        alert("Acceso denegado. No tienes permisos de Administrador.");
        window.location.href = "menu.html";
        return null;
    }
    return sesion;
}

// Destruye el token local y saca al usuario del sistema
function cerrarSesion() {
    localStorage.removeItem('sesion');
    sessionStorage.removeItem('cache_datos_generales');
    window.location.href = "index.html";
}

// =========================================================
// ⚡ CAPA DE CACHÉ DE DATOS — para que la app cargue más rápido
// =========================================================
// Antes, cada pantalla (menú, registro, pagos, estadísticas, etc.)
// llamaba a Google Apps Script por su cuenta cada vez que se abría,
// y GAS puede demorar varios segundos en responder. Ahora:
//  1. Si ya tenemos datos guardados de hace pocos segundos, se
//     muestran DE INMEDIATO (sin esperar a internet).
//  2. En paralelo, se pide la versión más nueva en segundo plano
//     y se actualiza la pantalla sola cuando llega.
// Esto hace que moverse entre pantallas se sienta instantáneo.
const CACHE_KEY = 'cache_datos_generales';
const CACHE_TTL_MS = 45000; // 45 segundos: tiempo en que el caché se considera "fresco"

function obtenerDatosGenerales(onData, forzarRefresco) {
    let cache = null;
    try {
        const crudo = sessionStorage.getItem(CACHE_KEY);
        if (crudo) cache = JSON.parse(crudo);
    } catch (e) {
        cache = null;
    }

    const ahora = Date.now();
    const cacheEsFresco = cache && (ahora - cache.timestamp < CACHE_TTL_MS);

    // 1) Si hay algo guardado, se lo mostramos ya mismo (aunque sea viejito)
    if (cache && !forzarRefresco) {
        onData(cache.datos, true);
        // Si el caché sigue fresco, no hace falta ir a buscar de nuevo
        if (cacheEsFresco) return;
    }

    // 2) Pedimos la versión actualizada a Google Apps Script
    fetch(`${GAS_URL}?action=general&t=${ahora}`)
        .then(res => res.json())
        .then(datos => {
            sessionStorage.setItem(CACHE_KEY, JSON.stringify({ datos, timestamp: Date.now() }));
            onData(datos, false);
        })
        .catch(err => {
            console.error("Error al obtener datos generales:", err);
            // Si no había caché previo, avisamos con null para que la pantalla muestre el error
            if (!cache) onData(null, false);
        });
}

// Se debe llamar después de guardar un servicio, un egreso o un bono,
// para que la próxima vez que se pidan datos, se traiga la versión nueva
// en vez de mostrar el caché desactualizado.
function invalidarCacheGeneral() {
    sessionStorage.removeItem(CACHE_KEY);
}

// 💡 Botón "lámpara" para cambiar entre tema claro (original) y tema oscuro.
// Se inyecta solo en cada página (no hace falta tocar los .html) y recuerda
// la preferencia del usuario con localStorage para que quede igual en todas.
(function () {
    const CLAVE_TEMA = 'psp_modo_claro';

    function aplicarTema() {
        const modoClaro = localStorage.getItem(CLAVE_TEMA) === '1';
        document.body.classList.toggle('modo-claro', modoClaro);
        const btn = document.getElementById('btnTema');
        if (btn) btn.textContent = modoClaro ? '💡' : '🌙';
    }

    function crearBotonTema() {
        if (document.getElementById('btnTema')) return;

        const btn = document.createElement('button');
        btn.id = 'btnTema';
        btn.type = 'button';
        btn.className = 'theme-toggle-btn';
        btn.title = 'Cambiar tema claro / oscuro';
        btn.addEventListener('click', function () {
            const modoClaroActual = localStorage.getItem(CLAVE_TEMA) === '1';
            localStorage.setItem(CLAVE_TEMA, modoClaroActual ? '0' : '1');
            aplicarTema();
        });

        document.body.appendChild(btn);
        aplicarTema();
    }

    if (document.readyState === 'loading') {
        document.addEventListener('DOMContentLoaded', crearBotonTema);
    } else {
        crearBotonTema();
    }
})();